import os
import torch


class Config:
    # =========================
    # Paths & Directories
    # =========================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the provided script
    TRAIN_METADATA = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA = os.path.join(METADATA_DIR, "test.csv")

    # Working directory for caching and artifacts (Idea 1)
    WORKING_DIR = "./working/idea_1"
    os.makedirs(WORKING_DIR, exist_ok=True)

    # Submission directory
    SUBMISSION_DIR = "./submission"
    os.makedirs(SUBMISSION_DIR, exist_ok=True)
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Model Checkpoint Path
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "best_model.pth")

    # =========================
    # General Settings
    # =========================
    SEED = 42
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4  # Optimized for 12 vCPUs

    # =========================
    # Data Parameters
    # =========================
    IMG_SIZE = 512  # Resizing images to 512x512
    PIXEL_MEAN = [0.485, 0.456, 0.406]  # ImageNet mean
    PIXEL_STD = [0.229, 0.224, 0.225]  # ImageNet std

    # =========================
    # Model Hyperparameters
    # =========================
    BACKBONE = "resnet18"

    # Detection Head: 2 classes (0: Background, 1: Opacity)
    NUM_DETECTION_CLASSES = 2

    # Study Classification Head: 4 classes
    # 0: Negative for Pneumonia
    # 1: Typical Appearance
    # 2: Indeterminate Appearance
    # 3: Atypical Appearance
    NUM_STUDY_CLASSES = 4

    # =========================
    # Training Settings
    # =========================
    BATCH_SIZE = 16  # Fits comfortably in A100 40GB with ResNet18
    LEARNING_RATE = 1e-4
    WEIGHT_DECAY = 1e-4
    NUM_EPOCHS = 12

    # Loss Weights
    RPN_BOX_LOSS_WEIGHT = 1.0
    RPN_CLS_LOSS_WEIGHT = 1.0
    ROI_BOX_LOSS_WEIGHT = 1.0
    ROI_CLS_LOSS_WEIGHT = 1.0
    STUDY_LOSS_WEIGHT = 1.0  # Weight for the auxiliary classification task

    # Early Stopping
    PATIENCE = 3

    # =========================
    # Inference / Post-processing
    # =========================
    IOU_THRESHOLD = 0.5  # For NMS
    CONF_THRESHOLD = 0.25  # Confidence threshold for visualization/submission

    # Label Maps
    STUDY_ID_TO_LABEL = {
        0: "Negative for Pneumonia",
        1: "Typical Appearance",
        2: "Indeterminate Appearance",
        3: "Atypical Appearance",
    }

    STUDY_LABEL_TO_ID = {v: k for k, v in STUDY_ID_TO_LABEL.items()}

    # Detection Label Map
    DETECTION_CLASSES = ["background", "opacity"]

    @staticmethod
    def print_config():
        print("=" * 30)
        print("CONFIGURATION")
        print("=" * 30)
        for key, value in Config.__dict__.items():
            if not key.startswith("__") and not isinstance(value, staticmethod):
                print(f"{key}: {value}")
        print("=" * 30)
